from pathlib import Path
import re
root=Path(__file__).resolve().parents[1]
p=root/'farm/our-farm.html'
s=p.read_text(encoding='utf-8')
def icon(paths):
 return '<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths+'</svg>'
leaf=icon('<path d="M16 29V14m0 7C5 21 3 10 3 5c9 0 13 6 13 13m0 0C16 8 22 4 29 3c0 10-4 16-13 17"/>')
