quality=icon('<circle cx="16" cy="12" r="9"/><circle cx="16" cy="12" r="5"/><path d="m10 20-3 10 9-4 9 4-3-10m-9-8 2 2 4-5"/>')
fruit=icon('<path d="M16 9c-9-7-17 7-10 16 4 5 7 1 10 1s6 4 10-1c7-9-1-23-10-16Zm0 0V3m0 3c4 0 7-2 8-5-5 0-7 1-8 5"/>')
people=icon('<circle cx="16" cy="8" r="4"/><circle cx="6" cy="13" r="3"/><circle cx="26" cy="13" r="3"/><path d="M9 28v-8a7 7 0 0 1 14 0v8ZM9 20a5 5 0 0 0-8 4v4h8m14-8a5 5 0 0 1 8 4v4h-8"/>')
hero='''<section class="farm-story-hero"><img src="../images/Farm/farm-2.jpg" alt="Rows of fruit trees at Green Techno Farm" fetchpriority="high"><div class="container"><p class="eyebrow">OUR FARM &amp; GALLERY</p><h1>Our Farm &amp;<br><em>Gallery</em></h1><p>A closer look at our farms, cultivation practices<br>and the fresh produce we grow.</p></div><svg class="story-wave" viewBox="0 0 1440 70" preserveAspectRatio="none" aria-hidden="true"><path d="M0 15C220 100 380 4 700 35S1100 70 1440 0V70H0Z" fill="#abc66c"/><path d="M0 38C220 110 380 20 700 48S1100 84 1440 23V70H0Z" fill="#faf8f3"/></svg></section>'''
facts=''.join('<div>'+svg+'<div><h3>'+title+'</h3><p>'+text+'</p></div></div>' for svg,title,text in [(pin,'Farm Location','Thanamalwila, Sri Lanka'),(field,'Farm Size','100+ Acres'),(leaf,'Farming Method','Responsible cultivation'),(quality,'Produce Quality','Premium &amp; Naturally Grown')])
about='''<section class="story-about container" id="about"><div class="story-about-copy"><p class="eyebrow">ABOUT OUR FARM</p><h2>Sustainable Farming<br>for Quality <em>Produce</em></h2><p>Located in Thanamalwila, Sri Lanka, our 100+ acre plantation is dedicated to cultivating high-quality, naturally grown fruits with care and responsible farming practices.</p><details class="farming-approach"><summary class="button">Our Farming Approach <span aria-hidden="true">&#8594;</span></summary><p>We nurture our fruit trees through regular care and monitoring, select produce carefully at harvest, and prepare each crop for supply. Contact our team to learn more about our cultivation practices.</p></details></div><img class="story-about-photo" src="../assets/media/farm-IMG_3243-1600.webp" alt="A view across the fruit plantation" loading="lazy"><aside class="story-facts" aria-label="Farm facts">'''+facts+'</aside></section>'
photos=[('farm-1.jpg','Papayas growing beneath a canopy of green leaves','produce'),('farm-2.jpg','Fruit trees and paths across our plantation','farm'),('farm-5.jpg','Freshly harvested green banana bunches','produce'),('3fb493d3-c47f-4b1f-b84f-c0d8c3741d56.jpeg','Tamarind growing on the tree','produce'),('farm-8.jpg','Green citrus fruit growing on our farm','produce'),('img-44.jpg','Fruit trees carefully tended on the plantation','cultivation'),('img-47.jpg','Bananas gathered and sorted after harvest','activities')]
filters=''.join('<button type="button" data-gallery-filter="'+key+'" aria-pressed="'+('true' if key=='all' else 'false')+'">'+svg+label+'</button>' for key,label,svg in [('all','All',''),('farm','Our Farm',leaf),('cultivation','Cultivation',field),('produce','Our Produce',fruit),('activities','Farm Activities',people)])
images=''.join('<button type="button" class="story-photo" data-category="'+category+'" aria-label="View photo: '+alt+'"><img src="../images/Farm/'+name+'" alt="'+alt+'" loading="lazy" decoding="async"></button>' for name,alt,category in photos)
gallery='''<section class="story-gallery" id="gallery"><div class="story-gallery-heading"><p class="eyebrow">OUR GALLERY</p><h2>Life at Green Techno Farm</h2><p>Explore our farms, cultivation practices and the journey of our fresh produce from farm to fruit.</p></div><div class="story-filters" aria-label="Filter gallery">'''+filters+'''</div><p class="gallery-status" role="status" aria-live="polite">Showing all 7 photos</p><div class="story-photo-grid">'''+images+'''</div></section><dialog class="story-lightbox" aria-label="Farm photograph"><button type="button" class="lightbox-close" aria-label="Close photograph">&#10005;</button><img alt=""><p></p></dialog>'''
cta='<section class="story-visit">'+leaf+'<div><h2>Visit Our Farm or Explore More</h2><p>Connect with our team to discuss a visit and discover our farming practices firsthand.</p></div><a class="button yellow" href="contact.html">Get in Touch <span aria-hidden="true">&#8594;</span></a></section>'
s=re.sub(r'<main id="main">.*?</main>', '<main id="main">'+hero+about+gallery+cta+'</main>',s,flags=re.S)
s=re.sub(r'</main><section class="cta">.*?</section><footer>','</main><footer>',s,flags=re.S)
s=s.replace('<body>','<body class="page-farm-story">')
if 'farm-story.css' not in s:s=s.replace('</head>','<link rel="stylesheet" href="../assets/css/farm-story.css"><script defer src="../assets/js/farm-gallery.js"></script></head>')
p.write_text(s,encoding='utf-8')
